#!/usr/bin/env bash
set -euo pipefail

SRC="/workspaces/Photon-Camera-fresh-iris"
OUTDIR="/workspaces/Photon-Camera/fresh_iris_outputs"
BRANCH="experimental-clean-photon-rebuild"
STAMP="$(date +%Y%m%d_%H%M%S)"
SCRIPT_NAME="build_26429_codespace_shared_guide_reference_structure.sh"

fail() {
  echo "FAIL: $*" >&2
  exit 1
}

sha() { sha256sum "$1" | awk '{print toupper($1)}'; }

cd "$SRC" || fail "Missing Codespace worktree: $SRC"
mkdir -p "$OUTDIR"

echo "============================================================"
echo "26429 CODESPACE - SHARED GUIDE ROBUSTNESS + REFERENCE STRUCTURE"
echo "============================================================"

echo "=== GATE 0: SYNC TO YOUR ALREADY-PUSHED EXPERIMENTAL BRANCH ==="
git fetch origin "$BRANCH"

# Do not destroy or reset any Codespace work.
if ! git diff --quiet || ! git diff --cached --quiet; then
  fail "Tracked Codespace changes exist. Nothing was reset. Preserve/review them before continuing."
fi
UNTRACKED_APP="$(git ls-files --others --exclude-standard -- app || true)"
if [[ -n "$UNTRACKED_APP" ]]; then
  echo "$UNTRACKED_APP"
  fail "Untracked files exist under app/. Nothing was reset."
fi

CURRENT_BRANCH="$(git branch --show-current)"
if [[ "$CURRENT_BRANCH" != "$BRANCH" ]]; then
  if git show-ref --verify --quiet "refs/heads/$BRANCH"; then
    git switch "$BRANCH"
  else
    git switch -c "$BRANCH" --track "origin/$BRANCH"
  fi
fi

git merge --ff-only "origin/$BRANCH"
LOCAL_HEAD="$(git rev-parse HEAD)"
REMOTE_HEAD="$(git rev-parse "origin/$BRANCH")"
[[ "$LOCAL_HEAD" == "$REMOTE_HEAD" ]] || fail "Codespace is not exactly at origin/$BRANCH"

echo "SYNC PASS"
echo "branch=$BRANCH"
echo "HEAD=$LOCAL_HEAD"

declare -A EXPECTED
EXPECTED['app/src/main/java/com/particlesdevs/photoncamera/processing/processor/MotionV2CfaReconstruction.java']='B5CA7F93F1444B7F3C880F97D7E474B072F650273A7E9C4DB51764034C3A1F7D'
EXPECTED['app/src/main/assets/shaders/motionv2/direct_rgb_init.glsl']='A3DC78DC0FFF692D23EEC9909D29A053839DAA16F67E90A4E552B9DF5A8CF7B3'
EXPECTED['app/src/main/assets/shaders/motionv2/direct_rgb_accumulate.glsl']='FE62CA5F04735EB2E2E6D7DB2E725431B2C8CB2D9A0B0482916FAA7569623002'
EXPECTED['app/src/main/assets/shaders/motionv2/color_transform.glsl']='3C0DBE63E08D2E1347294921BED2717902B99390DB8A73E7DB9E88CC5681EF0A'
EXPECTED['app/src/main/assets/shaders/motionv2/denoise.glsl']='5A939C709C181E61534233BECFABDE9C7C9A5A6296F3F362135832D03DC0FC0C'
EXPECTED['app/version.properties']='1D245D59983CD65526C586BFE3A0A7FD12B9EAEDCDE87508A1215C938A6FBC2F'

declare -A CAND_HASH
CAND_HASH['app/src/main/java/com/particlesdevs/photoncamera/processing/processor/MotionV2CfaReconstruction.java']='76CAC4E7FE2B185068ADE3F34D5BB04FA60E81FFF3E05D3027897501A9764874'
CAND_HASH['app/src/main/assets/shaders/motionv2/direct_rgb_init.glsl']='8E0D3A176280C49D17094BC318382F9C1AF97C76FFFA85ACA7B19053F516C5C1'
CAND_HASH['app/src/main/assets/shaders/motionv2/direct_rgb_accumulate.glsl']='A7BF945D386C881A9259A9626D2A7F69AE8A5DA998387248D484D91B9A50E221'
CAND_HASH['app/src/main/assets/shaders/motionv2/color_transform.glsl']='37D1312419889F869164911AEC982DA7C8F7FA7FE719D04F4B5D3ED00F88B33A'
CAND_HASH['app/version.properties']='344FFA4C4A7E7F52E0827A62E044647ADBD568093CC8D2B74E1A49CD3B2BAB90'

declare -A CAND_B64
CAND_B64['app/src/main/java/com/particlesdevs/photoncamera/processing/processor/MotionV2CfaReconstruction.java']=''
CAND_B64['app/src/main/assets/shaders/motionv2/direct_rgb_init.glsl']=''
CAND_B64['app/src/main/assets/shaders/motionv2/direct_rgb_accumulate.glsl']=''
CAND_B64['app/src/main/assets/shaders/motionv2/color_transform.glsl']=''
CAND_B64['app/version.properties']='I1dlZCBBdWcgMDUgMjI6NTY6MDQgRURUIDIwMjYKVkVSU0lPTl9OQU1FPTAuOTcyNjQyOQpWRVJTSU9OX0JVSUxEPTI2NDI5Cg=='

echo "=== GATE 1: EXACT 26428 PUSHED SOURCE ==="
for rel in "${!EXPECTED[@]}"; do
  [[ -f "$rel" ]] || fail "Missing baseline file: $rel"
  actual="$(sha "$rel")"
  [[ "$actual" == "${EXPECTED[$rel]}" ]] ||     fail "26428 hash mismatch: $rel expected=${EXPECTED[$rel]} actual=$actual"
done
grep -q '^VERSION_NAME=0\.9726428$' app/version.properties || fail "Expected VERSION_NAME 0.9726428"
grep -q '^VERSION_BUILD=26428$' app/version.properties || fail "Expected VERSION_BUILD 26428"
echo "PASS: exact pushed 26428 source proven"

SAFETY="$SRC/safety_26429_shared_guide_reference_structure_$STAMP"
CAND="$SAFETY/candidate"
ORIG="$SAFETY/originals"
mkdir -p "$CAND" "$ORIG"

BACKUP="backup/codespace-before-26429-shared-guide-reference-structure-$STAMP"
git branch "$BACKUP"

PREPATCH="$SAFETY/pre_26429_working_tree.patch"
git diff --binary HEAD -- app > "$PREPATCH"

STATUS_BEFORE="$SAFETY/status_before.txt"
git status --short --branch > "$STATUS_BEFORE"

TARGETS=(
  "app/src/main/java/com/particlesdevs/photoncamera/processing/processor/MotionV2CfaReconstruction.java"
  "app/src/main/assets/shaders/motionv2/direct_rgb_init.glsl"
  "app/src/main/assets/shaders/motionv2/direct_rgb_accumulate.glsl"
  "app/src/main/assets/shaders/motionv2/color_transform.glsl"
  "app/version.properties"
)

for rel in "${TARGETS[@]}"; do
  mkdir -p "$ORIG/$(dirname "$rel")"
  cp -a "$rel" "$ORIG/$rel"
done

PROTECTED_BEFORE="$SAFETY/protected_hashes_before.txt"
PROTECTED_AFTER="$SAFETY/protected_hashes_after.txt"

hash_protected() {
  local out="$1"
  : > "$out"
  while IFS= read -r -d '' f; do
    skip=0
    for t in "${TARGETS[@]}"; do
      [[ "$f" == "$t" ]] && skip=1 && break
    done
    [[ "$skip" -eq 1 ]] && continue
    printf '%s  %s\n' "$(sha "$f")" "$f" >> "$out"
  done < <(git ls-files -z app)
  sort -o "$out" "$out"
}

hash_protected "$PROTECTED_BEFORE"

echo "=== GATE 2: COMPLETE TEMPORARY CANDIDATES ==="
for rel in "${!CAND_B64[@]}"; do
  dst="$CAND/$rel"
  mkdir -p "$(dirname "$dst")"
  printf '%s' "${CAND_B64[$rel]}" | base64 -d > "$dst"
  actual="$(sha "$dst")"
  [[ "$actual" == "${CAND_HASH[$rel]}" ]] ||     fail "Candidate hash mismatch: $rel expected=${CAND_HASH[$rel]} actual=$actual"
done

CACC="$CAND/app/src/main/assets/shaders/motionv2/direct_rgb_accumulate.glsl"
CINIT="$CAND/app/src/main/assets/shaders/motionv2/direct_rgb_init.glsl"
CCOLOR="$CAND/app/src/main/assets/shaders/motionv2/color_transform.glsl"
CRECON="$CAND/app/src/main/java/com/particlesdevs/photoncamera/processing/processor/MotionV2CfaReconstruction.java"
CVERSION="$CAND/app/version.properties"

grep -q 'IRIS_26429_SHARED_GUIDE_ROBUSTNESS_REFERENCE_STRUCTURE' "$CACC" || fail "26429 accumulator marker missing"
grep -q 'sharedConfidence = clamp(flow.z' "$CACC" || fail "Shared flow confidence missing"
grep -q 'referenceGreenCell' "$CACC" || fail "Reference green structure authority missing"
grep -q 'sigmaAcross = mix(1.30,0.72' "$CACC" || fail "Safer accumulator cross-edge kernel missing"
! grep -q 'value-prediction' "$CACC" || fail "Old per-channel RGB prediction robustness survived"
! grep -q 'float prediction' "$CACC" || fail "Old per-channel prediction parameter survived"
! grep -q 'currentLuma' "$CACC" || fail "Evolving RGB still owns structure"
grep -q 'sigmaAcross = mix(1.30, 0.72' "$CINIT" || fail "Safer reference cross-edge kernel missing"
grep -q 'IRIS_26429_REFERENCE_CFA_STRUCTURE_BINDING' "$CRECON" || fail "Reference CFA Java binding marker missing"
grep -q '"referenceCfa", referenceCfa, false' "$CRECON" || fail "Reference CFA texture binding missing"
grep -q 'rgbPredictionRobustness=false' "$CRECON" || fail "26429 runtime architecture telemetry missing"
grep -q '^VERSION_NAME=0\.9726429$' "$CVERSION" || fail "Candidate version name mismatch"
grep -q '^VERSION_BUILD=26429$' "$CVERSION" || fail "Candidate build mismatch"

echo "candidate/source validation PASS"

echo "=== GATE 3: GLSL LEXICAL + REAL COMPILER VALIDATION ==="

VALIDATOR_PY="$SAFETY/validate_26429_glsl.py"
cat > "$VALIDATOR_PY" <<'PY'
from pathlib import Path
import re, sys

def strip_comments(s):
    s=re.sub(r'/\*.*?\*/',' ',s,flags=re.S)
    s=re.sub(r'//.*',' ',s)
    return s

color=Path(sys.argv[1]).read_text()
acc=Path(sys.argv[2]).read_text()
init=Path(sys.argv[3]).read_text()

color_code=strip_comments(color)
acc_code=strip_comments(acc)
init_code=strip_comments(init)

# Regression for the two 26427/26428 runtime failures.
if re.search(r'\bcoherent\b', color_code):
    raise SystemExit("FAIL: bare GLSL reserved token 'coherent' remains in executable color shader")
if 'coherentRgb=mix(coherentRgb,vec3(terminalEnergy),terminal);' not in color_code.replace(' ','').replace('\n',''):
    raise SystemExit("FAIL: corrected coherentRgb terminal expression missing")

# Architecture proof: no channel-specific feedback against evolving RGB.
for bad in ('value-prediction','float prediction','currentLuma'):
    if bad in acc_code:
        raise SystemExit("FAIL: old channel-feedback code remains: "+bad)
for good in ('sharedConfidence','flow.z','referenceCfa','referenceGreenCell'):
    if good not in acc_code:
        raise SystemExit("FAIL: 26429 shared/reference authority missing: "+good)

# Photon owns #version and compute workgroup injection.
for name,code in [('acc',acc),('init',init),('color',color)]:
    if re.search(r'(?m)^\s*#version\b',code):
        raise SystemExit("FAIL: candidate owns #version: "+name)

print("LEXICAL GLSL VALIDATION PASS")
PY

python3 "$VALIDATOR_PY" "$CCOLOR" "$CACC" "$CINIT"

if ! command -v glslangValidator >/dev/null 2>&1; then
  echo "glslangValidator not present; installing glslang-tools before any source modification..."
  if command -v sudo >/dev/null 2>&1; then
    sudo apt-get update
    sudo apt-get install -y glslang-tools
  else
    fail "glslangValidator is required for 26429 and sudo is unavailable"
  fi
fi
command -v glslangValidator >/dev/null 2>&1 || fail "glslangValidator installation failed"

WRAP_PY="$SAFETY/make_glslang_wrapper.py"
cat > "$WRAP_PY" <<'PY'
from pathlib import Path
import sys,re
src=Path(sys.argv[1]).read_text()
kind=sys.argv[2]
dst=Path(sys.argv[3])

if kind == 'comp':
    src=re.sub(r'(?m)^#define\s+LAYOUT\s+//\s*\nLAYOUT\s*\n',
               '',src,count=1)
    prefix='#version 310 es\nlayout(local_size_x=8, local_size_y=8, local_size_z=1) in;\n'
elif kind == 'frag':
    prefix='#version 310 es\n'
else:
    raise SystemExit('bad kind')
dst.write_text(prefix+src)
PY

ACC_WRAP="$SAFETY/direct_rgb_accumulate_26429.comp"
INIT_WRAP="$SAFETY/direct_rgb_init_26429.comp"
COLOR_WRAP="$SAFETY/color_transform_26429.frag"
DENOISE_WRAP="$SAFETY/denoise_26428.frag"

python3 "$WRAP_PY" "$CACC" comp "$ACC_WRAP"
python3 "$WRAP_PY" "$CINIT" comp "$INIT_WRAP"
python3 "$WRAP_PY" "$CCOLOR" frag "$COLOR_WRAP"
python3 "$WRAP_PY" "app/src/main/assets/shaders/motionv2/denoise.glsl" frag "$DENOISE_WRAP"

GLSL_LOG="$SAFETY/glslang_validation.txt"
{
  echo "=== direct_rgb_accumulate ==="
  glslangValidator -S comp "$ACC_WRAP"
  echo "=== direct_rgb_init ==="
  glslangValidator -S comp "$INIT_WRAP"
  echo "=== color_transform ==="
  glslangValidator -S frag "$COLOR_WRAP"
  echo "=== unchanged 26427/26428 denoise (never reached on device because color crashed first) ==="
  glslangValidator -S frag "$DENOISE_WRAP"
} 2>&1 | tee "$GLSL_LOG"

echo "GLSL COMPILER VALIDATION PASS"
echo "Temporary-copy validation: PASS"

echo "=== GATE 4: APPLY EXACT VALIDATED CANDIDATES ==="
for rel in "${!CAND_B64[@]}"; do
  cp "$CAND/$rel" "$rel"
done

echo "=== GATE 5: PRE-BUILD SAFETY PROOF ==="
for rel in "${!CAND_HASH[@]}"; do
  actual="$(sha "$rel")"
  [[ "$actual" == "${CAND_HASH[$rel]}" ]] ||     fail "Applied source differs from validated candidate: $rel"
done

hash_protected "$PROTECTED_AFTER"
cmp -s "$PROTECTED_BEFORE" "$PROTECTED_AFTER" || fail "A protected tracked app file changed"

git diff --check -- "${TARGETS[@]}"

# Re-run the exact lexical proof against applied source.
python3 "$VALIDATOR_PY" "app/src/main/assets/shaders/motionv2/color_transform.glsl" "app/src/main/assets/shaders/motionv2/direct_rgb_accumulate.glsl" "app/src/main/assets/shaders/motionv2/direct_rgb_init.glsl"

echo "candidate/source validation PASS"
echo "Temporary-copy validation: PASS"
echo "PRE-BUILD SAFETY PROOF PASSED"

POSTPATCH="$SAFETY/post_26429_working_tree.patch"
git diff --binary HEAD -- app > "$POSTPATCH"

echo "=== GATE 6: BUILD 0.9726429 / 26429 ==="
JAVA_BIN="$(command -v java || true)"
[[ -n "$JAVA_BIN" ]] || fail "Java not found"
java -version 2>&1 | tee "$SAFETY/java_version.txt"
chmod +x ./gradlew

BUILDLOG="$OUTDIR/build_26429_shared_guide_reference_structure_$STAMP.txt"
set +e
./gradlew :app:assembleDebug --stacktrace 2>&1 | tee "$BUILDLOG"
RC=${PIPESTATUS[0]}
set -e
[[ "$RC" -eq 0 ]] || fail "Gradle failed rc=$RC; see $BUILDLOG"
grep -q 'BUILD SUCCESSFUL' "$BUILDLOG" || fail "BUILD SUCCESSFUL not found in build log"

APK_SRC="$(find app/build/outputs/apk -type f -name '*.apk' -printf '%T@ %p\n' | sort -nr | head -1 | cut -d' ' -f2-)"
[[ -n "$APK_SRC" && -f "$APK_SRC" ]] || fail "Built APK not found"

APK_NAME="IrisCamera-0.9726429-26429-v2-shared-guide-reference-structure-debug.apk"
APK_ROOT="$SRC/$APK_NAME"
APK_OUT="$OUTDIR/$APK_NAME"
cp "$APK_SRC" "$APK_ROOT"
cp "$APK_SRC" "$APK_OUT"

RESULT="$OUTDIR/26429_SHARED_GUIDE_REFERENCE_STRUCTURE_RESULT_$STAMP.txt"
cat > "$RESULT" <<EOF
26429 SHARED GUIDE ROBUSTNESS + REFERENCE STRUCTURE
Timestamp: $(date --iso-8601=seconds)
Branch: $BRANCH
Base HEAD synced from remote: $LOCAL_HEAD
Version/build: 0.9726429 / 26429

WHY:
- Cross-scene evidence shows green/magenta separation on non-clipped neutral edges.
- 26426 had healthy temporal/per-channel support.
- 26426 nevertheless made R/G/B robustness decisions independently against evolving reconstructed RGB.
- MotionV2Alignment already supplies a shared green-guide confidence in flow.z.

CHANGES:
- Fixes 26428 GLSL reserved-word rename completely: coherentRgb reads coherentRgb.
- Removes per-channel value-vs-current-RGB robustness feedback from direct RGB accumulation.
- Uses one shared flow.z confidence for R/G/B CFA observations.
- Kernel geometry now comes from physical reference CFA green, not evolving RGB.
- Keeps real CFA photosite coordinates and one rawFlow x2 conversion.
- Widens minimum strong-edge cross-axis sigma from 0.44/0.48 to 0.72 raw px.
- Stretches strong-edge along-axis sigma to 2.40 raw px.
- Physical reference remains fallback; with current-RGB-independent weights the normalized sum is order-independent.
- Existing actual exposure normalization through frame.pair.layerMpy is untouched.
- 26427 coherent highlight clipping remains, with only its runtime syntax corrected.
- 26427 denoise remains byte-identical.
- No sharpening added.

SAFETY:
- Backup branch: $BACKUP
- Pre-edit binary patch: $PREPATCH
- Post-edit binary patch: $POSTPATCH
- GLSL compiler log: $GLSL_LOG
- Protected tracked app files hash-identical.
- candidate/source validation PASS
- Temporary-copy validation PASS
- PRE-BUILD SAFETY PROOF PASSED
- BUILD SUCCESSFUL verified.

APK repo root: $APK_ROOT
APK output copy: $APK_OUT
Build log: $BUILDLOG

No commit.
No push.
dev untouched.
EOF

echo "============================================================"
echo "BUILD SUCCESSFUL VERIFIED"
echo "APK: $APK_ROOT"
echo "APK COPY: $APK_OUT"
echo "RESULT: $RESULT"
echo "SAFETY: $SAFETY"
echo "No commit. No push. dev untouched."
echo "============================================================"
